<?php require __DIR__.'/_guard.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();$name=trim($_POST['name']);$sku=trim($_POST['sku']);$q=db()->prepare("INSERT INTO products(name,slug,sku,description,price,sale_price,cost_price,stock,low_stock_threshold,category_id,status,featured) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$q->execute([$name,slugify($name).'-'.bin2hex(random_bytes(2)),$sku,$_POST['description'],(float)$_POST['price'],($_POST['sale_price']!==''?(float)$_POST['sale_price']:null),(float)$_POST['cost_price'],(int)$_POST['stock'],(int)$_POST['threshold'],(int)($_POST['category_id']??0) ?: null,$_POST['status'],isset($_POST['featured'])?1:0]);$id=(int)db()->lastInsertId();if(!empty($_FILES['image']['name'])){$path=Security::upload($_FILES['image']);db()->prepare('INSERT INTO product_images(product_id,image_path) VALUES(?,?)')->execute([$id,$path]);}audit('product.create','product',$id);$msg='Product created';}$products=db()->query('SELECT id,name,sku,price,stock,status FROM products ORDER BY id DESC LIMIT 200')->fetchAll();$cats=db()->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main class="wide"><a href="/admin/">← Dashboard</a><h1>Product management</h1><p><?=e($msg)?></p><form method="post" enctype="multipart/form-data"><?=Security::field()?><div class="formgrid"><label>Product name<input name="name" required></label><label>SKU<input name="sku" required></label><label>Retail price<input type="number" step=".01" name="price" required></label><label>Sale price<input type="number" step=".01" name="sale_price"></label><label>Cost price<input type="number" step=".01" name="cost_price" value="0"></label><label>Stock<input type="number" name="stock" value="0"></label><label>Low stock threshold<input type="number" name="threshold" value="5"></label><label>Category<select name="category_id"><option value="">None</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="active">Active</option><option value="draft">Draft</option></select></label><label>Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label></div><label>Description<textarea name="description"></textarea></label><label><input type="checkbox" name="featured"> Featured</label><button>Create product</button></form><h2>Products</h2><table><tr><th>ID</th><th>Name</th><th>SKU</th><th>Price</th><th>Stock</th><th>Status</th></tr><?php foreach($products as $p):?><tr><td><?=$p['id']?></td><td><?=e($p['name'])?></td><td><?=e($p['sku'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><?=e($p['status'])?></td></tr><?php endforeach;?></table></main></body></html>